+QStringList RunnerMatchesModel::menuPath(const QString &storageId) const
+{
+    if (!m_menuPaths) {
+        m_menuPaths.emplace();
+        // Breadth-first, so an application listed in several places gets its least nested one
+        QList<std::pair<KServiceGroup::Ptr, QStringList>> groups{{KServiceGroup::root(), {}}};
+        while (!groups.isEmpty()) {
+            const auto [group, path] = groups.takeFirst();
+            if (!group || !group->isValid()) {
+                continue;
+            }
+            const KServiceGroup::List entries = group->entries(false /* sorted */, true /* excludeNoDisplay */);
+            for (const KSycocaEntry::Ptr &entry : entries) {
+                if (entry->isType(KST_KService)) {
+                    const QString id = static_cast<KService *>(entry.data())->storageId();
+                    if (!path.isEmpty() && !m_menuPaths->contains(id)) {
+                        m_menuPaths->insert(id, path);
+                    }
+                } else if (entry->isType(KST_KServiceGroup)) {
+                    const KServiceGroup::Ptr subGroup(static_cast<KServiceGroup *>(entry.data()));
+                    groups.append({subGroup, path + QStringList{subGroup->caption()}});
+                }
+            }
+        }
+    }
+    return m_menuPaths->value(storageId);
+}
+
